#!/usr/bin/env node
/**
 * extract-pages.mjs — machine extraction of the frozen design source.
 *
 * Reads design-source/pages/<slug>/code.html (the design truth, generated by
 * the handoff's own build pipeline) and emits src/content/pages/<slug>.ts with
 *   export const title / description / mainHtml
 * Rewrites:
 *   ../<slug>/code.html        -> <route>          (per route-mapping.json)
 *   ../<slug>/code.html#anchor -> <route>#anchor
 *   ../../assets/...           -> /assets/...
 * NOTHING else is touched — visible copy stays byte-identical to 05 freeze.
 */
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const DS = join(ROOT, 'design-source');
const OUT = join(ROOT, 'src', 'content', 'pages');

const mapping = JSON.parse(readFileSync(join(DS, 'route-mapping.json'), 'utf8'));
const slugToRoute = {};
for (const r of mapping.routes) {
  const slug = r.dir.replace(/^pages\//, '');
  slugToRoute[slug] = r.route;
}

function ts(str) {
  return '`' + str.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${') + '`';
}

function extractHead(html, slug) {
  const title = (html.match(/<title>([\s\S]*?)<\/title>/) || [])[1];
  const desc = (html.match(/<meta name="description" content="([^"]*)"/) || [])[1];
  if (!title || !desc) throw new Error(`[extract] ${slug}: missing title/description`);
  return { title, description: desc };
}

function extractMain(html, slug) {
  const m = html.match(/<main>([\s\S]*?)<\/main>/);
  if (!m) throw new Error(`[extract] ${slug}: no <main>`);
  return m[1];
}

function rewrite(html) {
  let out = html;
  // asset paths first (they share the ../../ prefix)
  out = out.replace(/(src|href)="(\.\.\/)*assets\//g, '$1="/assets/');
  // page links: ../<slug>/code.html with optional #anchor (and ../for/<slug>)
  out = out.replace(/href="\.\.\/([\w-]+(?:\/[\w-]+)?)\/code\.html(#[\w-]*)?"/g, (all, slug, anchor) => {
    // design slugs use dashes already; for/ pages are nested dirs
    const key = slug.includes('/') ? slug.replace('/', '-') : slug;
    const route = slugToRoute[key] ?? slugToRoute[slug];
    if (!route) throw new Error(`[extract] unknown page link slug: ${slug}`);
    const base = route === '/' ? '/' : route + '/';
    return `href="${base}${anchor || ''}"`;
  });
  return out;
}

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });

const index = [];
for (const r of mapping.routes) {
  const slug = r.dir.replace(/^pages\//, '');
  const html = readFileSync(join(DS, 'pages', slug, 'code.html'), 'utf8');
  const { title, description } = extractHead(html, slug);
  const mainHtml = rewrite(extractMain(html, slug)).trim();
  const file = join(OUT, `${slug}.ts`);
  writeFileSync(
    file,
    `// GENERATED by scripts/extract-pages.mjs from design-source/pages/${slug}/code.html\n` +
      `// DO NOT HAND EDIT — copy is frozen (05 v1.2 + §12). Re-run npm run extract.\n` +
      `export const title = ${ts(title)};\n` +
      `export const description = ${ts(description)};\n` +
      `export const mainHtml = ${ts(mainHtml)};\n`,
  );
  index.push({ slug, route: r.route, type: r.type, h1: r.h1, schema: r.schema });
  console.log(`extracted ${slug} -> ${r.route} (${mainHtml.length} bytes)`);
}

writeFileSync(
  join(OUT, 'index.ts'),
  `// GENERATED — route/slug registry\nexport const PAGES = ${JSON.stringify(index, null, 2)} as const;\n`,
);
console.log(`OK — ${index.length} pages extracted`);
